    [19117]={name="Laquered Wooden Plate Legplates",quality=2,ilvl=50,sourceType="quest_reward",instructions="Reward from the quest 'Separation Anxiety'. Pick it over the other reward choices.",zone="The Hinterlands",questName="Separation Anxiety",lore="Like many in our village, I too have lost a loved one to the wilds. Alas, it was my twin brother Malkhor - taken in the same raid as Torntusk's mate by the Vilebranch."},
