    [21134]={name="Dark Edge of Insanity",quality=4,ilvl=84,reqLevel=60,sourceType="boss_drop",instructions="Drops from C'Thun.",zone="Temple of Ahn'Qiraj",npc="C'Thun",lore="An Old God, buried under Ahn'Qiraj by the titans rather than killed. It has been whispering to the qiraji ever since, and the whole war exists because it never stopped.",proc="Chance on hit: Disorients the target, causing it to wander aimlessly for up to 3 sec."},
    [21180]={name="Earthstrike",quality=4,ilvl=66,sourceType="quest_reward",instructions="Reward from the quest 'Champion's Battlegear'. Pick it over the other reward choices.",zone="Silithus",questName="Champion's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Cenarion Hold are more than just for show. You'd be wise to hold on to them.",proc="Use: Increases your melee and ranged attack power by 280.  Effect lasts for 20 sec. (2 Min Cooldown)"},
    [21184]={name="Deeprock Bracers",quality=4,ilvl=62,sourceType="quest_reward",instructions="Reward from the quest 'Stalwart's Battlegear'. Pick it over the other reward choices.",zone="Silithus",questName="Stalwart's Battlegear",lore="The badges you collect from performing combat, logistics and tactical assignments for Windcaller Proudhorn are more than just for show. You'd be wise to hold on to them."},
    [21316]={name="Leggings of the Ursa",quality=2,ilvl=55,sourceType="quest_reward",instructions="Reward from the quest 'Deadwood of the North'. Pick it over the other reward choices.",zone="Timbermaw Hold",questName="Deadwood of the North",lore="There is a camp of Deadwood furbolgs directly to our southwest. Corruption permeates the camp, and I wish to put an end to it before they become a problem."},
    [21387]={name="Avenger's Crown",quality=4,ilvl=81,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Avenger's Crown'.",zone="Ahn'Qiraj",questName="Avenger's Crown",lore="The Twin Emperors... their incessant whispers are slowly taking a toll on my sanity. They mock me, knowing I cannot step further into their domain to save my brother Arygos."},
    [21388]={name="Avenger's Greaves",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Avenger's Greaves'.",zone="Ahn'Qiraj",questName="Avenger's Greaves",lore="Qiraji magic is strong and ancient. The most powerful qiraji wield items of such might, they'd give pause even to a dragon."},
    [21389]={name="Avenger's Breastplate",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Avenger's Breastplate'.",zone="Ahn'Qiraj",questName="Avenger's Breastplate",lore="The unmentionable Old God slowly awakens from his slumber beneath Ahn'Qiraj. The terrible fate that awaits Azeroth could come in days or years; time has no meaning for beings of his power."},
    [21391]={name="Avenger's Pauldrons",quality=4,ilvl=78,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Avenger's Pauldrons'.",zone="Ahn'Qiraj",questName="Avenger's Pauldrons",lore="Bring me the bindings worn by the highest Qiraji leaders and I shall shape them into a set of pauldrons more dreadful than even the wings of Nefarian himself!"},
    [21397]={name="Cape of Eternal Justice",quality=4,ilvl=67,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Cape of Eternal Justice'.",zone="Ahn'Qiraj",questName="Cape of Eternal Justice",lore="I'm glad to hear you're aiding us in our attack on Ahn'Qiraj. I can make you a protective item that'll be of assistance in the fight against our enemy."},
    [21507]={name="Amulet of the Shifting Sands",quality=4,ilvl=70,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'The Fall of Ossirian'. Pick it over the other reward choices.",zone="Ruins of Ahn'Qiraj",questName="The Fall of Ossirian",lore="A terrible menace has been laid to rest. The cruel Ossirian has been vanquished. The denizens of Kalimdor would be relieved to know of this victory."},
    [21567]={name="Rune of Duty",quality=3,ilvl=45,reqLevel=40,sourceType="vendor",instructions="Bought from the Warsong Gulch quartermaster with marks of honor. Alliance: Illiyana Moonblaze at Silverwing Grove, Ashenvale. Horde: Kelm Hargunth at Mor'shan Base Camp, The Barrens."},
